        <head>
          <title>Dynamic Content Updates Test</title>
        </head>
        <body>
          <div role="main">
            <h1>Dynamic Content Updates</h1>

            <div id="live-region" role="status" aria-live="polite" aria-atomic="true">
              Initial content
            </div>

            <div id="alert-region" role="alert" aria-live="assertive">
              Alert region ready
            </div>

            <button id="update-button">Update Content</button>
            <button id="alert-button">Trigger Alert</button>
            <button id="form-status">Submit Form</button>

            <div id="form-feedback" role="status" aria-live="polite" aria-atomic="true">
              Form ready for input
            </div>

            <div id="loading-indicator" role="status" aria-live="polite" aria-label="Loading">
              <span aria-hidden="true">⏳</span>
            </div>

            <div id="notification-container" role="region" aria-label="Notifications" aria-live="polite">
              No notifications
            </div>
          </div>

          <script>
            document.getElementById('update-button').addEventListener('click', () => {
              const liveRegion = document.getElementById('live-region');
              liveRegion.textContent = 'Content has been updated successfully at ' + new Date().toLocaleTimeString();
            });

            document.getElementById('alert-button').addEventListener('click', () => {
              const alertRegion = document.getElementById('alert-region');
              alertRegion.textContent = 'Critical alert: System update required immediately';
            });

            document.getElementById('form-status').addEventListener('click', () => {
              const formFeedback = document.getElementById('form-feedback');
              formFeedback.textContent = 'Form submitted successfully. Confirmation email sent.';
            });
          </script>
        </body>
      </html>
    `);
  });

