    const liveRegion = page.getByRole('status').first();

    // Verify initial content
    await expect(liveRegion).toHaveText('Initial content');

    // Trigger update
    const updateButton = page.getByRole('button', { name: 'Update Content' });
    await updateButton.click();

    // Verify content was updated
    const updatedText = await liveRegion.textContent();
    expect(updatedText).toContain('Content has been updated successfully');

    // Verify aria-live attribute is set to polite
    await expect(liveRegion).toHaveAttribute('aria-live', 'polite');

    // Verify aria-atomic is true for complete announcement
    await expect(liveRegion).toHaveAttribute('aria-atomic', 'true');
  });

  test('should announce urgent alerts via assertive live region', async ({ page }) => {
    const alertRegion = page.getByRole('alert');

    // Verify initial state
    await expect(alertRegion).toHaveText('Alert region ready');

    // Trigger alert
    const alertButton = page.getByRole('button', { name: 'Trigger Alert' });
    await alertButton.click();

    // Verify alert content was updated
    await expect(alertRegion).toHaveText('Critical alert: System update required immediately');

    // Verify aria-live is set to assertive for urgent announcements
    await expect(alertRegion).toHaveAttribute('aria-live', 'assertive');
  });

  test('should announce form submission feedback to screen readers', async ({ page }) => {
    const formFeedback = page.getByRole('status').filter({ hasText: 'Form ready' });

    // Verify initial form status
    await expect(formFeedback).toHaveText('Form ready for input');

    // Submit form
    const submitButton = page.getByRole('button', { name: 'Submit Form' });
    await submitButton.click();

    // Verify feedback was announced
    await expect(formFeedback).toHaveText('Form submitted successfully. Confirmation email sent.');

    // Verify live region attributes for accessibility
    await expect(formFeedback).toHaveAttribute('aria-live', 'polite');
    await expect(formFeedback).toHaveAttribute('aria-atomic', 'true');
  });

  test('should maintain proper ARIA attributes for notification region', async ({ page }) => {
    const notificationRegion = page.getByRole('region', { name: 'Notifications' });

    // Verify region is properly labeled
    await expect(notificationRegion).toHaveAttribute('aria-label', 'Notifications');

    // Verify live region is set to polite
    await expect(notificationRegion).toHaveAttribute('aria-live', 'polite');

    // Verify initial content
    await expect(notificationRegion).toHaveText('No notifications');
  });

  test('should properly handle loading indicator with accessible label', async ({ page }) => {
    const loadingIndicator = page.getByRole('status', { name: 'Loading' });

    // Verify loading indicator has proper ARIA label
    await expect(loadingIndicator).toHaveAttribute('aria-label', 'Loading');

    // Verify live region is set for announcements
    await expect(loadingIndicator).toHaveAttribute('aria-live', 'polite');

    // Verify decorative content is hidden from screen readers
